import sys, os
# Ensure project root is on sys.path
sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))

import tensorflow as tf
from tensorflow.keras.models import Sequential
from tensorflow.keras.layers import Conv2D, MaxPooling2D, GlobalAveragePooling2D, Dense, Dropout, BatchNormalization
from tensorflow.keras.preprocessing.image import ImageDataGenerator
from sklearn.metrics import roc_auc_score

# Model Architecture
def create_model(input_shape=(96, 96, 1), num_classes=234):
    model = Sequential([
        Conv2D(32, (3, 3), activation='relu', input_shape=input_shape),
        MaxPooling2D((2, 2)),
        BatchNormalization(),
        
        Conv2D(64, (3, 3), activation='relu'),
        MaxPooling2D((2, 2)),
        BatchNormalization(),
        
        Dropout(0.25),
        
        Conv2D(128, (3, 3), activation='relu'),
        MaxPooling2D((2, 2)),
        BatchNormalization(),
        
        GlobalAveragePooling2D(),
        
        Dense(256, activation='relu'),
        Dropout(0.5),
        
        Dense(num_classes, activation='sigmoid')
    ])
    
    model.compile(optimizer='adam',
                  loss='binary_crossentropy',
                  metrics=[tf.keras.metrics.AUC(multi_label=True)])
    return model

# Data Loading
data_dir = "/home/carme/birdclef-data"
batch_size = 32

train_datagen = ImageDataGenerator(rescale=1./255, validation_split=0.2)
train_generator = train_datagen.flow_from_directory(
    data_dir,
    target_size=(96, 96),
    batch_size=batch_size,
    class_mode='binary',
    subset='training'
)

validation_generator = train_datagen.flow_from_directory(
    data_dir,
    target_size=(96, 96),
    batch_size=batch_size,
    class_mode='binary',
    subset='validation'
)

# Model Training
model = create_model()
history = model.fit(
    train_generator,
    steps_per_epoch=train_generator.samples // batch_size,
    validation_data=validation_generator,
    validation_steps=validation_generator.samples // batch_size,
    epochs=10  # Adjust as needed based on time constraints
)

# Evaluation
def evaluate_model(model, generator):
    y_true = generator.classes
    y_pred = model.predict(generator)
    auc_score = roc_auc_score(y_true, y_pred, average='macro', multi_class='ovr')
    return auc_score

validation_auc = evaluate_model(model, validation_generator)
print(f"Validation AUC: {validation_auc}")